<document source="src/transport/ws/conversationList.ts" type="code" relevance="1.00" tokens="533">
async function answerOne(
  ws: WebSocket,
  session: Pick<ChatSession, 'sessionId' | 'userId'>,
  frame: ListConversationsMessage,
  deps?: ConversationListDeps
): Promise<void> {
  const {sessionId, userId} = session;
  // A handler built without the store cannot serve the frame either, and silence is the one answer never to give.
  if (deps === undefined || !deps.history?.enabled) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled on this server');
    return;
  }
  // Refused rather than answered empty: a client told "no conversations" cannot tell that from a user who has none.
  const {listFor} = deps.sessionStore;
  if (listFor === undefined) {
    sendError(ws, ErrorCodes.UNSUPPORTED, 'This session store cannot list conversations');
    return;
  }

  // The deployer's switch, never the client's: the frame has no field for it and the validator would drop one.
  const preview = deps.history.preview === true;
  let conversations: ConversationSummary[];
  // Only the read and the mapping of what it answered: a send that fails is this socket's fault, not the store's.
  try {
    const summaries = await listFor.call(deps.sessionStore, userId, {
      limit: frame.limit,
      before: frame.before,
      preview,
    });
    conversations = summaries.map(preview ? withPreview : onTheWire);
  } catch (error) {
    if (error instanceof StoreCannotList) {
      // A store saying it cannot list at all is a deployment fault, not a failed read: the client hears the same as above.
      log.error('message', 'store cannot list conversations', {sessionId, userId, errorType: error.name});
      sendError(ws, ErrorCodes.UNSUPPORTED, 'This session store cannot list conversations');
      return;
    }
    // The type alone, as the authenticator path does it: a driver's message can carry a connection string and its password.
    log.error('message', 'conversation list failed', {sessionId, userId, errorType: typeOf(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
    return;
  }

  sendJson(ws, {type: 'conversation_list', conversations});
}
</document>
<document source="src/transport/ws/messageHandler.ts" type="code" relevance="0.98" tokens="203">
// Off the per-session lock: neither frame here is a turn, and a list that queued behind a streaming answer looks broken.
async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  deps: MessageHandlerDeps | undefined,
  signal: AbortSignal | undefined
): Promise<void> {
  if (reportInvalid(ws, validation)) return;

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  // Abandoned when its socket has closed; otherwise answered even by a handler with no store, since silence is no answer.
  if (message.type !== 'list_conversations' || signal?.aborted) return;

  // The session's own user, never a user the frame names: the frame has no field for one.
  await answerConversationList(ws, session, message, deps);
}
</document>
<document source="src/transport/ws/validation.ts" type="code" relevance="0.89" tokens="187">
// Accepted whether or not the feature is on: a validator reads a frame, and the handler decides what is served.
function validateListConversations(message: Record<string, unknown>): ValidationResult {
  const {limit, before} = message;
  if (limit !== undefined && !isPage(limit)) {
    return {valid: false, error: `list_conversations limit must be a whole number from 1 to ${MAX_LIMIT}`};
  }

  const cursor = before === undefined ? undefined : asCursor(before);
  if (before !== undefined && cursor === undefined) {
    return {valid: false, error: 'list_conversations before must carry an ISO updatedAt and a sessionId'};
  }

  return {valid: true, data: {type: 'list_conversations', limit: limit as number | undefined, before: cursor}};
}
</document>
